class Solution {
    public int closestGap(int[] heights) {
        int n = heights.length, best = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                best = Math.min(best, Math.abs(heights[i] - heights[j]));
        return best;
    }
}

