int closestGap(int* heights, int heightsSize) {
    int best = INT_MAX;
    for (int i = 0; i < heightsSize; i++)
        for (int j = i + 1; j < heightsSize; j++) {
            int d = abs(heights[i] - heights[j]);
            if (d < best) best = d;
        }
    return best;
}

