class Solution {
    public int closestGap(int[] heights) {
        int[] s = heights.clone();
        Arrays.sort(s);
        int best = Integer.MAX_VALUE;
        for (int i = 0; i + 1 < s.length; i++) best = Math.min(best, s[i + 1] - s[i]);
        return best;
    }
}

