class Solution {
public:
    int closestGap(vector<int>& heights) {
        vector<int> s = heights;
        sort(s.begin(), s.end());
        int best = INT_MAX;
        for (size_t i = 0; i + 1 < s.size(); i++) best = min(best, s[i + 1] - s[i]);
        return best;
    }
};

