static int cmpInt(const void* a, const void* b) {
    int p = *(const int*) a, q = *(const int*) b;
    return (p > q) - (p < q);
}

int closestGap(int* heights, int heightsSize) {
    int* s = malloc(heightsSize * sizeof(int));
    memcpy(s, heights, heightsSize * sizeof(int));
    qsort(s, heightsSize, sizeof(int), cmpInt);
    int best = INT_MAX;
    for (int i = 0; i + 1 < heightsSize; i++) if (s[i + 1] - s[i] < best) best = s[i + 1] - s[i];
    free(s);
    return best;
}
